// Mindset Injector: Converts the user's choice into a specific research persona
const pillar = $input.first().json.Pillar;
const seed = $input.first().json.Topic_Seed || 'the latest high-value AI automation trend for SMEs';
let mindset = '';

if (pillar === 'Curiosity Detour') {
  // Focus: Economic ROI & Hidden Human OpEx
  mindset = `Act as a Lean Operations Consultant. Research the unit economics of "${seed}" with a focus on 'Manual Debt'. 
  Specifically search for 2025-2026 data on 'Human-in-the-loop' (HITL) overhead—quantify the labor hours spent correcting hallucinations or manual reformatting. 
  Find the 'Breakeven Point' where this trend becomes a net loss in OpEx compared to traditional methods.`;

} else if (pillar === 'Low-Level Insight') {
  // Focus: Retrieval Accuracy & Accuracy Benchmarks
  mindset = `Conduct a technical audit of "${seed}" focusing strictly on Retrieval Accuracy. 
  Search for 2025-2026 benchmarks using frameworks like RAGAS or TruLens. 
  Specifically look for Recall@K, MRR (Mean Reciprocal Rank), and F1 scores. 
  Identify 'Silent Failures'—cases where the system retrieves incorrect data without triggering error flags.`;

} else if (pillar === 'Brutalist Review') {
  // Focus: Air-Gapped Sovereignty & Telemetry
  mindset = `Perform a 'Brutalist' infrastructure review of "${seed}" for a 'Dark Site' (air-gapped) environment. 
  Search for 'Phone-home' telemetry, background pings, and mandatory cloud dependencies. 
  Determine if the binary/container can run 100% offline. 
  Map all external dependencies and rate its 'Sovereignty Score' from 1 (Cloud-Tethered) to 10 (True Air-Gapped).`;
}

return [{
  json: {
    topic: seed,
    pillar: pillar,
    perplexity_prompt: mindset
  }
}];

// Extract media URLs from Perplexity citations and prepare Gemini prompt
const response = $input.first().json;
const citations = response.citations || [];
const content = response.choices?.[0]?.message?.content || '';

// Extract image URLs from content
const urlRegex = /https?:\/\/[^\s\"<>]+\.(?:png|jpg|jpeg|gif|webp|svg)/gi;
const contentUrls = content.match(urlRegex) || [];

// Combine citations and extracted URLs, deduplicate, filter valid URLs
const allUrls = [...new Set([...citations, ...contentUrls])]
  .filter(url => url && (url.startsWith('http://') || url.startsWith('https://')));

// Prepare Gemini prompt
const topic = $('Mindset Injector').item.json.topic;
const geminiPrompt = `Research: ${content}\n\nTopic: ${topic}`;

return [{
  json: {
    research_content: content,
    media_urls: allUrls,
    citations: citations,
    gemini_prompt: geminiPrompt
  }
}];

